-- [TRAIVL PROJECT MASTER INITIALIZATION V12]
-- 이 스크립트는 프로젝트의 전체 데이터 구조와 130개의 고품질 여행 데이터를 초기화합니다.

CREATE EXTENSION IF NOT EXISTS vector;

-- [1] 테이블 초기화 (기존 데이터 삭제)
DROP TABLE IF EXISTS "Place" CASCADE;
DROP TABLE IF EXISTS "User" CASCADE;
DROP TABLE IF EXISTS "Destination" CASCADE;

-- [2] 사용자(User) 테이블 정의
-- 용도: 테스트용 유저 세션 및 DNA 분석 결과를 저장함.
CREATE TABLE "User" (
    id TEXT PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    name TEXT,
    "password" TEXT,
    "profileImage" TEXT,
    "dnaType" TEXT,
    "destinationId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- [3] 도시(Destination) 테이블 정의
-- 용도: 메인 화면의 실시간 인기 도시 노출 및 사용자 DNA 기반 추천의 기준이 됨.
CREATE TABLE "Destination" (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    country TEXT NOT NULL,
    "dnaType" TEXT NOT NULL,
    description TEXT,
    "imageUrl" TEXT,
    currency TEXT,
    language TEXT,
    voltage TEXT,
    "visaRequired" TEXT,
    "bestSeason" TEXT[],
    "averageCost" INTEGER
);

-- [4] 상세 장소(Place) 테이블 정의
-- 용도: 사용자가 도시를 선택했을 때 노출되는 '맛집/명소' 리스트 및 상세 팝업용 데이터.
CREATE TABLE "Place" (
    id SERIAL PRIMARY KEY,
    "destinationId" TEXT NOT NULL REFERENCES "Destination"(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    "imageUrl" TEXT,
    description TEXT,
    rating DOUBLE PRECISION,
    rank INTEGER NOT NULL,
    address TEXT,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    "openingHours" TEXT,
    "phoneNumber" TEXT,
    tags TEXT[],
    "averagePrice" INTEGER
);

-- [5] 기본 데이터 삽입
-- 테스트를 위한 기본 유저 생성

-- [6] 도시 데이터 삽입 (Destination)
-- * 실시간 인기 도시 연동군 (1~8번): 서울, 제주, 부산, 속초, 오사카, 교토, 도쿄, 후쿠오카
-- * 일반 추천/결과 호출군 (9~13번): 오키나와, 파리, 바르셀로나, 로마, 베를린

